name: migrate-module
description: Migrates one service module from callback-style database access to the matching repository class, then runs that module's tests. Use when the user names a single service file to migrate. Handles exactly one module per invocation.
---

# Repository pattern migration

The mapping table from callback call to repository method:

| Callback call in a service | Repository method |
|---|---|
| `query('users', u => u.deleted_at === null, cb)` | `UserRepository.findActive()` |
| `query('users', u => u.id === id, cb)` | `UserRepository.findById(id)` |
| `update('users', id, { deleted_at }, cb)` | `UserRepository.softDelete(id, when)` |
| `query('orders', o => o.user_id === id ..., cb)` | `OrderRepository.findByUser(id)` |
| `query('orders', o => o.status === 'paid' ..., cb)` | `OrderRepository.findPaid()` |

Steps:

1. Read the target service file and its test file.
2. Replace every direct `query`/`update` import and call with the matching repository method.
3. Convert the exported functions to return promises. Update the test file to await them.
4. Run only that module's tests: `node --test tests/<module>.test.js`.
5. Stop after three failed attempts and report what blocked you.

`payments` has no repository yet. If the target is `payment-service.js`, create
`src/repositories/payment-repository.js` following the shape of the other two.
import { query } from '../db.js';

// Callback-style database access. Chapter 5 migrates this to UserRepository.
export function findByEmail(email, callback) {
  query('users', (u) => u.email === email && u.deleted_at === null, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows[0] ?? null);
  });
}

export function isActive(email, callback) {
  findByEmail(email, (err, user) => {
    if (err) return callback(err);
    callback(null, Boolean(user));
  });
}
import { query } from '../db.js';

// Callback-style database access. Chapter 5 migrates this to OrderRepository.
export function listOrdersForUser(userId, callback) {
  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
}

export function totalPaidCents(callback) {
  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
  });
}
import { query } from '../db.js';

// Callback-style database access. Chapter 5 migrates this to a PaymentRepository
// the reader adds, which is the part of the exercise with no worked answer.
export function findPaymentsForOrder(orderId, callback) {
  query('payments', (p) => p.order_id === orderId, callback);
}

export function uncapturedTotalCents(callback) {
  query('payments', (p) => p.captured === false, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows.reduce((sum, p) => sum + p.amount_cents, 0));
  });
}
import { query, update } from '../db.js';

// Callback-style database access. Chapter 5 migrates this to UserRepository.
export function listActiveUsers(callback) {
  query('users', (u) => u.deleted_at === null, callback);
}

export function findUser(id, callback) {
  query('users', (u) => u.id === id, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows[0] ?? null);
  });
}

export function softDeleteUser(id, when, callback) {
  update('users', id, { deleted_at: when }, callback);
}
// A deliberately tiny in-memory database with a callback API.
// The callback style is the point: Chapter 5 migrates the service layer off it.

const tables = {
  users: [
    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
  ],
  orders: [
    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
  ],
  payments: [
    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
  ],
};

export function reset() {
  tables.users[2].deleted_at = '2026-01-04';
  tables.orders.forEach((o) => { o.deleted_at = null; });
}

// Old-style callback query. Accepts a table name and a predicate.
export function query(table, predicate, callback) {
  setImmediate(() => {
    const rows = tables[table];
    if (!rows) return callback(new Error(`no such table: ${table}`));
    try {
      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
    } catch (err) {
      callback(err);
    }
  });
}

export function update(table, id, patch, callback) {
  setImmediate(() => {
    const row = (tables[table] || []).find((r) => r.id === id);
    if (!row) return callback(new Error(`no row ${id} in ${table}`));
    Object.assign(row, patch);
    callback(null, { ...row });
  });
}
import { query } from '../db.js';

export class OrderRepository {
  findByUser(userId) {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findPaid() {
    return new Promise((resolve, reject) => {
      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }
}
import { query, update } from '../db.js';

// The repository pattern the project is migrating toward: promise-based,
// one place per table, no query construction anywhere else.
export class UserRepository {
  findActive() {
    return new Promise((resolve, reject) => {
      query('users', (u) => u.deleted_at === null, (err, rows) =>
        err ? reject(err) : resolve(rows));
    });
  }

  findById(id) {
    return new Promise((resolve, reject) => {
      query('users', (u) => u.id === id, (err, rows) =>
        err ? reject(err) : resolve(rows[0] ?? null));
    });
  }

  softDelete(id, when) {
    return new Promise((resolve, reject) => {
      update('users', id, { deleted_at: when }, (err, row) =>
        err ? reject(err) : resolve(row));
    });
  }
}

